export interface Receipt { id: number; tenant: string; key: string; cents: number }

/**
 * Keyed idempotency store: (tenant, key) -> receipt of the committed debit.
 * A reservation is recorded synchronously, before the first `await`, so a
 * concurrent `apply` for the same tenant/key can never start a second debit.
 */
class IdempotencyStore {
  private readonly reserved = new Map<string, Receipt>();

  keyOf(tenant: string, key: string): string {
    return `${tenant}\u0000${key}`;
  }

  get(tenant: string, key: string): Receipt | undefined {
    return this.reserved.get(this.keyOf(tenant, key));
  }

  reserve(receipt: Receipt): void {
    this.reserved.set(this.keyOf(receipt.tenant, receipt.key), receipt);
  }
}

export class Ledger {
  readonly entries: Receipt[] = [];
  private readonly store = new IdempotencyStore();

  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    if (typeof tenant !== 'string' || !tenant ||
        typeof key !== 'string' || !key ||
        !Number.isInteger(cents) || cents <= 0) {
      throw new Error('invalid payment');
    }
    // Idempotency is scoped by tenant and key. The reservation is taken
    // synchronously (no await before it), so repeated or concurrent applies
    // with an equal amount return the original receipt and never re-debit;
    // an unequal amount for the same tenant/key is a conflict.
    const reserved = this.store.get(tenant, key);
    if (reserved) {
      if (reserved.cents !== cents) throw new Error('key conflict');
      return reserved;
    }
    const receipt: Receipt = { id: this.entries.length + 1, tenant, key, cents };
    this.entries.push(receipt);
    this.store.reserve(receipt);
    return receipt;
  }
}
