import { Ledger, Receipt } from './ledger';
import { Transient, Transport } from './transport';

export class PaymentService {
  constructor(private readonly ledger: Ledger, private readonly transport: Transport) {}

  async pay(tenant: string, key: string, cents: number, attempts = 3): Promise<Receipt> {
    // Validate everything before any ledger or transport action.
    if (typeof tenant !== 'string' || !tenant ||
        typeof key !== 'string' || !key ||
        !Number.isInteger(cents) || cents <= 0 ||
        !Number.isInteger(attempts) || attempts < 1 || attempts > 5) {
      throw new Error('invalid payment');
    }
    let lastError: unknown;
    for (let n = 0; n < attempts; n++) {
      try {
        // Idempotent on (tenant, key): once a debit committed, apply returns
        // the original receipt, so every retry forwards the same receipt and
        // never duplicates the debit. Equal-amount replays return it as-is;
        // an unequal amount throws 'key conflict' (not retried).
        const receipt = await this.ledger.apply(tenant, key, cents);
        await this.transport.acknowledge(receipt);
        return receipt;
      } catch (error) {
        lastError = error;
        // Only Transient is retried; everything else (including 'key conflict')
        // propagates immediately. When retries are exhausted the final thrown
        // exception is preserved.
        if (!(error instanceof Transient)) throw error;
      }
    }
    throw lastError;
  }
}
