const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

class FlakyTransport {
  constructor(failFirst) { this.failFirst = failFirst; this.calls = []; this.acks = []; }
  async acknowledge(receipt) {
    this.calls.push(receipt);
    if (this.calls.length <= this.failFirst) throw new Transient('flaky');
    this.acks.push(receipt);
  }
}

async function main() {
  // 1. Baseline: single debit, acked once.
  {
    const ledger = new Ledger();
    const t = new FlakyTransport(0);
    const svc = new PaymentService(ledger, t);
    const r = await svc.pay('shop', 'sale', 123);
    assert.deepEqual(r, { id: 1, tenant: 'shop', key: 'sale', cents: 123 });
    assert.equal(ledger.entries.length, 1);
    assert.equal(t.calls.length, 1);
  }

  // 2. Retry on Transient: same receipt forwarded each time, exactly one debit.
  {
    const ledger = new Ledger();
    const t = new FlakyTransport(2); // fails twice, succeeds on 3rd
    const svc = new PaymentService(ledger, t);
    const r = await svc.pay('shop', 'sale', 500, 3);
    assert.equal(r.cents, 500);
    assert.equal(ledger.entries.length, 1, 'no duplicate debit on retry');
    assert.equal(t.calls.length, 3, 'three tries total');
    assert.ok(t.calls.every(c => c === r), 'same receipt forwarded each try');
    assert.equal(t.acks.length, 1);
  }

  // 3. Exhausted retries: final exception preserved, still only one debit.
  {
    const ledger = new Ledger();
    const err = new Transient('down');
    const svc = new PaymentService(ledger, { acknowledge: async () => { throw err; } });
    await assert.rejects(svc.pay('shop', 'sale', 50, 3), e => {
      assert.equal(e, err, 'final thrown exception is the last original error');
      return true;
    });
    assert.equal(ledger.entries.length, 1, 'one debit despite 3 tries');
  }

  // 4. Non-Transient errors are not retried.
  {
    const ledger = new Ledger();
    let calls = 0;
    const svc = new PaymentService(ledger, { acknowledge: async () => { calls++; throw new Error('permanent'); } });
    await assert.rejects(svc.pay('shop', 'sale', 9, 3), /permanent/);
    assert.equal(calls, 1, 'no retry for non-Transient');
  }

  // 5. Idempotent replay: equal amount returns original receipt, no new debit, no re-ack.
  {
    const ledger = new Ledger();
    const t = new FlakyTransport(0);
    const svc = new PaymentService(ledger, t);
    const r1 = await svc.pay('shop', 'sale', 123);
    const r2 = await svc.pay('shop', 'sale', 123);
    assert.equal(r1, r2, 'replay returns the original receipt');
    assert.equal(ledger.entries.length, 1);
  }

  // 6. Key conflict: same tenant/key with another amount throws, no new debit.
  {
    const ledger = new Ledger();
    const svc = new PaymentService(ledger, { acknowledge: async () => {} });
    await svc.pay('shop', 'sale', 100);
    await assert.rejects(svc.pay('shop', 'sale', 200), /key conflict/);
    assert.equal(ledger.entries.length, 1, 'no debit on conflict');
  }

  // 7. Idempotency scoped by tenant: same key, different tenants are independent.
  {
    const ledger = new Ledger();
    const svc = new PaymentService(ledger, { acknowledge: async () => {} });
    const a = await svc.pay('a', 'sale', 100);
    const b = await svc.pay('b', 'sale', 100);
    assert.notEqual(a, b);
    assert.equal(ledger.entries.length, 2);
  }

  // 8. Concurrency: two concurrent equal-amount calls -> one debit, same receipt.
  {
    const ledger = new Ledger();
    const svc = new PaymentService(ledger, { acknowledge: async () => {} });
    const [p1, p2] = [svc.pay('shop', 'sale', 77), svc.pay('shop', 'sale', 77)];
    const [r1, r2] = await Promise.all([p1, p2]);
    assert.equal(r1, r2, 'concurrent equal calls share the receipt');
    assert.equal(ledger.entries.length, 1, 'no duplicate debit under concurrency');
  }

  // 9. Concurrent conflicting amounts -> one debit, one 'key conflict'.
  {
    const ledger = new Ledger();
    const svc = new PaymentService(ledger, { acknowledge: async () => {} });
    const results = await Promise.allSettled([svc.pay('shop', 'sale', 10), svc.pay('shop', 'sale', 20)]);
    const fulfilled = results.filter(r => r.status === 'fulfilled');
    const rejected = results.filter(r => r.status === 'rejected');
    assert.ok(fulfilled.length === 1 && rejected.length === 1, 'exactly one winner');
    assert.match(rejected[0].reason.message, /key conflict/);
    assert.equal(ledger.entries.length, 1);
  }

  // 10. Validation before any ledger/transport action.
  {
    const ledger = new Ledger();
    let acks = 0;
    const svc = new PaymentService(ledger, { acknowledge: async () => { acks++; } });
    for (const args of [
      ['', 'k', 100], ['t', '', 100], ['t', 'k', 0], ['t', 'k', -5],
      ['t', 'k', 1.5], ['t', 'k', NaN], ['t', 'k', 100, 0],
      ['t', 'k', 100, 6], ['t', 'k', 100, 2.5],
    ]) {
      await assert.rejects(svc.pay(...args), /invalid payment/, `rejects ${JSON.stringify(args)}`);
    }
    assert.equal(ledger.entries.length, 0, 'validation precedes ledger');
    assert.equal(acks, 0, 'validation precedes transport');
    // boundaries accepted
    await svc.pay('t', 'k', 1, 1);
    await svc.pay('t', 'k2', 1, 5);
    assert.equal(ledger.entries.length, 2);
  }

  console.log('payment checks passed');
}

module.exports = main();
EOF
